import"./chunk-VC46IEJQ.js";var e=(h,d,o,t,i,l,s,r,n,a)=>({name:{en:h,zh:d},desc:{en:o[0],zh:o[1]},tour:{en:t[0],zh:t[1]},...a?{spoiler:{en:a[0],zh:a[1]}}:{},source:{confidence:i,refs:l,book:{en:s[0],zh:s[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:n[0],zh:n[1]}}}),f={id:"sunspear",intro:{en:"Sunspear, seat of House Martell, stands on a sun-baked spit of the Dornish coast, with the sea on three sides and the maze-like Shadow City on the fourth. The novels sketch it in a few vivid strokes; this scene fills in the rest.",zh:"\u9633\u621F\u57CE\u662F\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u5728\u591A\u6069\u6D77\u5CB8\u4E00\u5904\u70C8\u65E5\u7099\u70E4\u7684\u5CAC\u89D2\u4E0A\uFF0C\u4E09\u9762\u4E34\u6D77\uFF0C\u53E6\u4E00\u9762\u662F\u8FF7\u5BAB\u822C\u7684\u5F71\u5B50\u57CE\u3002\u5C0F\u8BF4\u53EA\u4EE5\u5BE5\u5BE5\u6570\u7B14\u52FE\u52D2\u6B64\u5730\uFF0C\u5176\u4F59\u7686\u7531\u672C\u573A\u666F\u8865\u5168\u3002"},notes:{en:"From the novels (A Feast for Crows, A Dance with Dragons): a castle on a promontory; the dun-coloured Sandship; the tall, slender Spear Tower topped with a gilded spear; the domed Tower of the Sun; the Old Palace; the Shadow City enclosed by the Winding Walls and pierced by the Threefold Gate; the Water Gardens a few leagues along the coast. Invented: all plans, spacing, building shapes and the harbour. The Water Gardens are drawn far closer than in the books.",zh:"\u5C0F\u8BF4\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u786E\u7ACB\uFF1A\u5CAC\u89D2\u4E0A\u7684\u57CE\u5821\uFF1B\u571F\u9EC4\u8272\u7684\u6C99\u8239\uFF1B\u9876\u7AEF\u7ACB\u7740\u9540\u91D1\u957F\u77DB\u7684\u7EC6\u9AD8\u957F\u77DB\u5854\uFF1B\u7A79\u9876\u7684\u592A\u9633\u5854\uFF1B\u65E7\u5BAB\uFF1B\u7531\u873F\u8712\u57CE\u5899\u56F4\u5408\u3001\u88AB\u4E09\u91CD\u95E8\u8D2F\u7A7F\u7684\u5F71\u5B50\u57CE\uFF1B\u6CBF\u6D77\u5CB8\u6570\u91CC\u683C\u5916\u7684\u6D41\u6C34\u82B1\u56ED\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5168\u90E8\u5E03\u5C40\u3001\u95F4\u8DDD\u3001\u5EFA\u7B51\u9020\u578B\u4E0E\u6E2F\u53E3\u3002\u6D41\u6C34\u82B1\u56ED\u5728\u573A\u666F\u4E2D\u88AB\u753B\u5F97\u6BD4\u4E66\u4E2D\u8FD1\u5F97\u591A\u3002"},tour:["spear-tower","tower-of-the-sun","sandship","old-palace","threefold-gate","winding-walls","shadow-city","harbour","water-gardens"],sources:[{ref:"affc",checked:"memory",note:{en:"Areo Hotah's and Arianne's chapters (A Feast for Crows, continued in A Dance with Dragons) supply most of the description; Oberyn's background comes from A Storm of Swords. Recalled, not re-read.",zh:"\u5927\u90E8\u5206\u63CF\u5199\u6765\u81EA\u963F\u5229\u6B27\xB7\u4F55\u5854\u4E0E\u4E9A\u83B2\u6069\u7684\u7AE0\u8282\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF0C\u5EF6\u7EED\u81F3\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\uFF1B\u5965\u67CF\u4F26\u7684\u80CC\u666F\u89C1\u4E8E\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"The Spear Tower, Tower of the Sun, Sandship, Shadow City, Threefold Gate and the distance to the Water Gardens were checked against web-search summaries of the wiki; pages not fetched.",zh:"\u957F\u77DB\u5854\u3001\u592A\u9633\u5854\u3001\u6C99\u8239\u3001\u5F71\u5B50\u57CE\u3001\u4E09\u91CD\u95E8\u53CA\u6D41\u6C34\u82B1\u56ED\u7684\u8DDD\u79BB\uFF0C\u7ECF\u7EF4\u57FA\u7684\u641C\u7D22\u6458\u8981\u6838\u5BF9\uFF1B\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{"spear-tower":e("Spear Tower","\u957F\u77DB\u5854",["The tallest, slenderest tower of the castle, crowned with a spear of gilded steel.","\u57CE\u5821\u4E2D\u6700\u9AD8\u6700\u7EC6\u7684\u5854\uFF0C\u9876\u7AEF\u7ACB\u7740\u4E00\u652F\u9540\u91D1\u94A2\u77DB\u3002"],["Sailors' first sight of Sunspear: a golden spear above the heat haze.","\u6C34\u624B\u671B\u89C1\u9633\u621F\u57CE\u7684\u7B2C\u4E00\u773C\uFF1A\u70ED\u6D6A\u4E4B\u4E0A\u7684\u4E00\u652F\u91D1\u77DB\u3002"],"high",["affc","awoiaf"],["A slender tower about 150 ft tall, topped by a gilded steel spear that adds some 30 ft more.","\u4E00\u5EA7\u9AD8\u7EA6\u4E00\u767E\u4E94\u5341\u5C3A\u7684\u7EC6\u5854\uFF0C\u9876\u7AEF\u7684\u9540\u91D1\u94A2\u77DB\u53C8\u9AD8\u51FA\u7EA6\u4E09\u5341\u5C3A\u3002"],["Its diameter and interior.","\u76F4\u5F84\u4E0E\u5185\u90E8\u7ED3\u6784\u3002"],["A tapering shaft with a gold spear and a few lit windows.","\u6536\u5206\u7684\u5854\u8EAB\uFF0C\u91D1\u77DB\u9AD8\u8038\uFF0C\u51E0\u6247\u7A97\u900F\u51FA\u706F\u5149\u3002"],["After a failed plot, Arianne is confined in a cell near the top of the Spear Tower.","\u4E00\u573A\u5BC6\u8C0B\u5931\u8D25\u540E\uFF0C\u4E9A\u83B2\u6069\u88AB\u8F6F\u7981\u5728\u957F\u77DB\u5854\u9876\u5C42\u9644\u8FD1\u7684\u56DA\u5BA4\u4E2D\u3002"]),"tower-of-the-sun":e("Tower of the Sun","\u592A\u9633\u5854",["A domed tower roofed in gold and leaded glass, where the ruling prince holds court from a high seat.","\u7A79\u9876\u4EE5\u9EC4\u91D1\u4E0E\u94C5\u6846\u73BB\u7483\u8986\u76D6\u7684\u5854\u697C\uFF0C\u7EDF\u6CBB\u591A\u6069\u7684\u4EB2\u738B\u5728\u6B64\u9AD8\u5750\u7406\u653F\u3002"],["Beneath the dome of gold and glass sits the ruler of Dorne.","\u91D1\u4E0E\u73BB\u7483\u7684\u7A79\u9876\u4E4B\u4E0B\uFF0C\u5750\u7740\u591A\u6069\u7684\u7EDF\u6CBB\u8005\u3002"],"high",["affc","awoiaf"],["A tower with a dome of gold and leaded glass, holding the princely seats; one bears the Martell spear and one the Rhoynish sun.","\u7A79\u9876\u4EE5\u9EC4\u91D1\u4E0E\u94C5\u6846\u73BB\u7483\u7B51\u6210\uFF0C\u5854\u5185\u8BBE\u4EB2\u738B\u5EA7\u4F4D\uFF1A\u4E00\u5F20\u5D4C\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u7684\u957F\u77DB\uFF0C\u4E00\u5F20\u5D4C\u6D1B\u4F0A\u62FF\u4EBA\u7684\u592A\u9633\u3002"],["Number of floors and the hall's layout.","\u697C\u5C42\u6570\u91CF\u4E0E\u5927\u5385\u5E03\u5C40\u3002"],["A round sandstone drum with a gold dome and a clear glass inner dome.","\u5706\u5F62\u7802\u5CA9\u5854\u8EAB\uFF0C\u91D1\u8272\u5916\u7A79\u9876\u4E0E\u900F\u660E\u73BB\u7483\u5185\u7A79\u9876\u3002"]),sandship:e("Sandship","\u6C99\u8239",["The oldest part of the castle, a dun-coloured mass shaped like a huge stone dromond aground, with later towers rising from it.","\u57CE\u5821\u6700\u53E4\u8001\u7684\u90E8\u5206\uFF0C\u571F\u9EC4\u8272\u7684\u5E9E\u5927\u5EFA\u7B51\uFF0C\u5F62\u5982\u4E00\u8258\u6401\u6D45\u7684\u5DE8\u578B\u77F3\u9020\u6218\u8239\uFF0C\u540E\u4E16\u7684\u5854\u697C\u7531\u6B64\u62D4\u8D77\u3002"],["The oldest hold looks like a great stone ship run aground.","\u6700\u53E4\u8001\u7684\u57CE\u5821\u5B9B\u5982\u4E00\u8258\u6401\u6D45\u7684\u5DE8\u5927\u77F3\u8239\u3002"],"medium",["affc","awoiaf"],["The Sandship, a dun-coloured, ship-shaped stronghold, is the original seat of the Martells from before Nymeria's coming; the later Rhoynar built around it.","\u6C99\u8239\u662F\u571F\u9EC4\u8272\u7684\u8239\u5F62\u5821\u5792\uFF0C\u662F\u5A1C\u6885\u8389\u4E9A\u5230\u6765\u4E4B\u524D\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u7684\u539F\u59CB\u5C45\u57CE\uFF1B\u540E\u6765\u7684\u6D1B\u4F0A\u62FF\u4EBA\u56F4\u7ED5\u5B83\u6269\u5EFA\u3002"],["Its dimensions and interior.","\u5C3A\u5BF8\u4E0E\u5185\u90E8\u7ED3\u6784\u3002"],["A layered stone hull with raised prow and stern and three domed towers.","\u5C42\u53E0\u7684\u77F3\u8D28\u8239\u4F53\uFF0C\u8239\u9996\u8239\u5C3E\u7FD8\u8D77\uFF0C\u4E0A\u7ACB\u4E09\u5EA7\u7A79\u9876\u5854\u3002"]),"old-palace":e("Old Palace","\u65E7\u5BAB",["The walled complex of halls, courtyards and domes at the heart of Sunspear, rising above the sea.","\u9633\u621F\u57CE\u6838\u5FC3\u5904\u57CE\u5899\u73AF\u7ED5\u7684\u5BAB\u6BBF\u7FA4\uFF0C\u5385\u5802\u3001\u5EAD\u9662\u4E0E\u7A79\u9876\u9519\u843D\uFF0C\u4E34\u6D77\u800C\u7ACB\u3002"],["The Old Palace: halls and courtyards under bleached domes.","\u65E7\u5BAB\uFF1A\u892A\u767D\u7684\u7A79\u9876\u4E0B\uFF0C\u5385\u5802\u4E0E\u5EAD\u9662\u76F8\u8FDE\u3002"],"medium",["affc","awoiaf"],["The Old Palace is the castle proper, reached through the Threefold Gate.","\u65E7\u5BAB\u5373\u57CE\u5821\u672C\u4F53\uFF0C\u7ECF\u4E09\u91CD\u95E8\u53EF\u8FBE\u3002"],["Wall circuit and room layout.","\u57CE\u5899\u8D70\u5411\u4E0E\u623F\u95F4\u5E03\u5C40\u3002"],["An eight-sided wall, five domed halls and a colonnaded courtyard.","\u516B\u8FB9\u5F62\u57CE\u5899\u3001\u4E94\u5EA7\u7A79\u9876\u5927\u6BBF\u4E0E\u4E00\u5EA7\u67F1\u5ECA\u5EAD\u9662\u3002"]),"threefold-gate":e("Threefold Gate","\u4E09\u91CD\u95E8",["Three gates set one behind another in the Winding Walls, so a visitor can pass straight through to the Old Palace.","\u873F\u8712\u57CE\u5899\u4E0A\u524D\u540E\u6392\u6210\u4E00\u7EBF\u7684\u4E09\u9053\u57CE\u95E8\uFF0C\u6765\u5BA2\u53EF\u4EE5\u7531\u6B64\u7B14\u76F4\u7A7F\u884C\uFF0C\u76F4\u62B5\u65E7\u5BAB\u3002"],["Three gates in a line: the only straight road to the palace.","\u4E09\u95E8\u4E00\u7EBF\uFF1A\u901A\u5F80\u5BAB\u6BBF\u7684\u552F\u4E00\u76F4\u8DEF\u3002"],"high",["affc","awoiaf"],["At the Threefold Gate three successive gates are aligned, giving a direct route through the walls to the Old Palace without threading the Shadow City.","\u4E09\u91CD\u95E8\u7531\u524D\u540E\u76F8\u7EE7\u7684\u4E09\u9053\u57CE\u95E8\u6392\u6210\u4E00\u7EBF\uFF0C\u65E0\u987B\u7A7F\u884C\u5F71\u5B50\u57CE\u7684\u8857\u5DF7\uFF0C\u5373\u53EF\u76F4\u901A\u65E7\u5BAB\u3002"],["The gates' appearance and size.","\u57CE\u95E8\u7684\u6837\u8C8C\u4E0E\u5C3A\u5BF8\u3002"],["Shown as one broad gatehouse flanked by two bastions, a simplification of the three aligned gates.","\u8868\u73B0\u4E3A\u4E00\u5EA7\u5BBD\u5927\u7684\u57CE\u95E8\u697C\u4E0E\u4E24\u4FA7\u7889\u697C\uFF0C\u662F\u5BF9\u4E09\u95E8\u4E00\u7EBF\u7684\u7B80\u5316\u3002"]),"winding-walls":e("Winding Walls","\u873F\u8712\u57CE\u5899",["Curving walls that turn the Shadow City into a maze of narrow alleys, courts and bazaars.","\u66F2\u6298\u7684\u57CE\u5899\u628A\u5F71\u5B50\u57CE\u9694\u6210\u7531\u7A84\u5DF7\u3001\u9662\u843D\u4E0E\u96C6\u5E02\u7EC4\u6210\u7684\u8FF7\u5BAB\u3002"],["These walls bend the streets into a maze that baffles strangers.","\u8FD9\u4E9B\u57CE\u5899\u8BA9\u8857\u9053\u66F2\u6298\u56DE\u73AF\uFF0C\u5916\u4EBA\u8FDB\u6765\u4FBF\u6655\u5934\u8F6C\u5411\u3002"],"high",["affc","awoiaf"],["The Winding Walls coil through the Shadow City, creating its maze of alleys, courts and bazaars.","\u873F\u8712\u57CE\u5899\u5728\u5F71\u5B50\u57CE\u4E2D\u76D8\u7ED5\uFF0C\u9020\u5C31\u4E86\u7A84\u5DF7\u3001\u9662\u843D\u4E0E\u96C6\u5E02\u4EA4\u9519\u7684\u8FF7\u5BAB\u3002"],["Their number and height.","\u57CE\u5899\u7684\u9053\u6570\u4E0E\u9AD8\u5EA6\u3002"],["Four sinuous low walls running north to south.","\u56DB\u9053\u5357\u5317\u8D70\u5411\u7684\u873F\u8712\u77EE\u5899\u3002"]),"shadow-city":e("Shadow City","\u5F71\u5B50\u57CE",["The sprawling town of mud-brick shops and hovels in the shadow of the castle's walls and towers.","\u5728\u57CE\u5821\u9AD8\u5899\u4E0E\u5854\u697C\u7684\u9634\u5F71\u4E0B\u8513\u5EF6\u7684\u57CE\u9547\uFF0C\u6CE5\u7816\u5E97\u94FA\u4E0E\u964B\u5C4B\u9CDE\u6B21\u6809\u6BD4\u3002"],["The town sprawls in the palace's shadow, loud and crowded.","\u57CE\u9547\u5728\u5BAB\u6BBF\u7684\u9634\u5F71\u4E0B\u94FA\u5C55\u5F00\u6765\uFF0C\u55A7\u95F9\u800C\u62E5\u6324\u3002"],"high",["affc","awoiaf"],["A crowded town of shops and hovels on the landward side, within the Winding Walls.","\u9646\u4FA7\u873F\u8712\u57CE\u5899\u4E4B\u5185\u62E5\u6324\u7684\u57CE\u9547\uFF0C\u904D\u5E03\u5E97\u94FA\u4E0E\u964B\u5C4B\u3002"],["Population, trades and street names.","\u4EBA\u53E3\u3001\u884C\u4E1A\u4E0E\u8857\u540D\u3002"],["Several hundred flat-roofed houses with a few domes.","\u6570\u767E\u5EA7\u5E73\u9876\u623F\u5C4B\uFF0C\u70B9\u7F00\u51E0\u5904\u7A79\u9876\u3002"]),harbour:e("Harbour","\u6E2F\u53E3",["Small piers and warehouses where trading ships and galleys come and go.","\u5C0F\u578B\u6808\u6865\u4E0E\u8D27\u6808\uFF0C\u5546\u8239\u4E0E\u6868\u5E06\u8239\u5F80\u6765\u5176\u95F4\u3002"],["Sea trade keeps the Dornish coast alive.","\u6D77\u4E0A\u8D38\u6613\u7EF4\u7CFB\u7740\u591A\u6069\u6D77\u5CB8\u7684\u751F\u673A\u3002"],"low",["affc"],["Sunspear faces the sea and ships call there, but no harbour layout is described.","\u9633\u621F\u57CE\u9762\u6D77\uFF0C\u4E5F\u6709\u8239\u53EA\u5F80\u6765\uFF0C\u4F46\u4E66\u4E2D\u672A\u63CF\u5199\u6E2F\u53E3\u5E03\u5C40\u3002"],["Harbour layout, size and name.","\u6E2F\u53E3\u5E03\u5C40\u3001\u89C4\u6A21\u4E0E\u540D\u79F0\u3002"],["Two piers and a row of warehouses on the north shore.","\u5317\u5CB8\u4E24\u5EA7\u6808\u6865\u4E0E\u4E00\u6392\u8D27\u6808\u3002"]),"water-gardens":e("Water Gardens","\u6D41\u6C34\u82B1\u56ED",["A cool pleasure palace of pools and fountains along the coast, Prince Doran's refuge. It is drawn much closer here than in the books.","\u6CBF\u6D77\u5CB8\u800C\u5EFA\u7684\u6E05\u51C9\u79BB\u5BAB\uFF0C\u6C60\u5858\u4E0E\u55B7\u6CC9\u9519\u843D\uFF0C\u662F\u9053\u6717\u4EB2\u738B\u7684\u907F\u5C45\u4E4B\u6240\u3002\u573A\u666F\u4E2D\u628A\u5B83\u753B\u5F97\u6BD4\u4E66\u4E2D\u8FD1\u5F97\u591A\u3002"],["Pools, fountains and shade: Prince Doran's retreat, some leagues from Sunspear.","\u6C34\u6C60\u3001\u55B7\u6CC9\u4E0E\u7EFF\u836B\uFF1A\u9053\u6717\u4EB2\u738B\u7684\u9690\u5C45\u4E4B\u5730\uFF0C\u79BB\u9633\u621F\u57CE\u6709\u6570\u91CC\u683C\u4E4B\u9065\u3002"],"high",["affc","awoiaf"],["A palace of pink marble with pools and fountains, built by a Martell prince for his Targaryen bride, a few leagues from Sunspear along the coast.","\u4E00\u5EA7\u7C89\u8272\u5927\u7406\u77F3\u5BAB\u6BBF\uFF0C\u6C34\u6C60\u4E0E\u55B7\u6CC9\u904D\u5E03\uFF0C\u662F\u4E00\u4F4D\u9A6C\u6CF0\u5C14\u4EB2\u738B\u4E3A\u5176\u5766\u683C\u5229\u5B89\u65B0\u5A18\u6240\u5EFA\uFF0C\u6CBF\u6D77\u5CB8\u8DDD\u9633\u621F\u57CE\u6570\u91CC\u683C\u3002"],["Its layout and size.","\u5E03\u5C40\u4E0E\u89C4\u6A21\u3002"],["Four domed pavilions around three pools in a walled court.","\u56F4\u5899\u5EAD\u9662\u4E2D\uFF0C\u56DB\u5EA7\u7A79\u9876\u4EAD\u9601\u73AF\u7ED5\u4E09\u65B9\u6C34\u6C60\u3002"])}};export{f as default};
